80. export function useMedicationDispenseData(
81.   chargeItems: ChargeItemRead[] | undefined,
82. ): UseMedicationDispenseDataResult {
83.   const { t } = useTranslation();
84. 
85.   const dispenseIds =
86.     chargeItems?.reduce((ids: string[], item) => {
87.       if (
88.         item.service_resource ===
89.           ChargeItemServiceResource.medication_dispense &&
90.         item.service_resource_id
91.       ) {
92.         ids.push(item.service_resource_id);
93.       }
94.       return ids;
95.     }, []) || [];
96. 
97.   // Get medication dispense charge items
98.   const dispenseQueries = useQueries({
99.     queries: dispenseIds.map((id) => ({
100.       queryKey: ["medication_dispense_retrieve", id],
101.       queryFn: query(medicationDispenseApi.get, { pathParams: { id } }),
102.     })),
103.   });
104. 
105.   const isLoadingDispenses = dispenseQueries.some((result) => result.isLoading);
106.   const hasDispenseErrors = dispenseQueries.some((result) => result.isError);
107. 
108.   const dispenseMap: Record<string, MedicationDispenseRead | undefined> = {};
109.   dispenseQueries.forEach((result, index) => {
110.     if (result.data) {
111.       dispenseMap[dispenseIds[index]] = result.data;
112.     }
113.   });
114. 
115.   // Show toast on error (only once using ref)
116.   const hasShownErrorToast = useRef(false);
117.   useEffect(() => {
118.     if (
119.       hasDispenseErrors &&
120.       !isLoadingDispenses &&
121.       !hasShownErrorToast.current
122.     ) {
123.       toast.error(t("failed_to_load_medication_details"));
124.       hasShownErrorToast.current = true;
125.     }
126.   }, [hasDispenseErrors, isLoadingDispenses, t]);
127. 
128.   return {
129.     dispenseMap,
130.     isLoadingDispenses,
131.     hasDispenseErrors,
132.   };
133. }
